/**
 * The driver must reproduce vspark exactly. expected_outputs.json was generated by running the
 * same clips through vspark's real SignalGraph engine with MEDIAPIPE_PIPELINE_TEMPLATE (pose
 * branch, broadcast swapped for a sink) at the snapshot in SOURCE.md. `@capture5` variants fire
 * "Capture head neutral" after frame 5.
 */
import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { BaselineSolver, renderStage, type OutputFrame } from '../src/pipeline.js';
import { parseFrame } from '../src/cli.js';

const FIX = path.join(path.dirname(fileURLToPath(import.meta.url)), 'fixtures');
const read = (f: string) => JSON.parse(fs.readFileSync(path.join(FIX, f), 'utf8'));
const clips: Record<string, { frames: Record<string, unknown>[] }> = {
  ...read('webcam_arm_clips.json').clips,
  ...read('synthetic_face_clip.json').clips,
};
const expected: Record<string, (OutputFrame | null)[]> = read('expected_outputs.json').outputs;
const T0 = 1_000_000;

describe('baseline solver matches the vspark engine', () => {
  for (const [key, want] of Object.entries(expected)) {
    it(key, () => {
      const [name, cap] = key.split('@capture');
      const captureAt = cap === undefined ? -1 : Number(cap);
      const solver = new BaselineSolver();
      const log = console.log;
      console.log = () => {};
      try {
        clips[name].frames.forEach((raw, i) => {
          const f = parseFrame(raw);
          const got = solver.step({ ...f, t: T0 + f.t });
          const ref = want[i];
          expect(!!got).toBe(!!ref);
          if (got && ref) {
            expect(Object.keys(got.bones).sort()).toEqual(Object.keys(ref.bones).sort());
            for (const [bone, q] of Object.entries(ref.bones))
              q.forEach((v, j) => expect(got.bones[bone][j]).toBeCloseTo(v, 12));
          }
          if (i === captureAt) solver.capture('head', T0 + f.t);
        });
      } finally {
        console.log = log;
      }
    });
  }
});

describe('render stage', () => {
  it('ticks at the render rate and leaves a constant pose unchanged', () => {
    const q: [number, number, number, number] = [0.1, 0.2, 0.3, Math.sqrt(1 - 0.14)];
    const poses = [0, 100, 200].map((t) => ({ t, bones: { neck: q } }));
    const out = renderStage(poses, { hz: 50 });
    expect(out.map((o) => o.t)).toEqual([0, 20, 40, 60, 80, 100, 120, 140, 160, 180, 200]);
    for (const o of out) o.bones.neck.forEach((v, j) => expect(v).toBeCloseTo(q[j], 9));
  });

  it('lags behind a step change (One Euro smoothing is active)', () => {
    const a: [number, number, number, number] = [0, 0, 0, 1];
    const b: [number, number, number, number] = [0, Math.sin(0.5), 0, Math.cos(0.5)];
    const out = renderStage([{ t: 0, bones: { neck: a } }, { t: 100, bones: { neck: b } }], { hz: 60 });
    const last = out[out.length - 1].bones.neck;
    expect(last[1]).toBeGreaterThan(0);
    expect(last[1]).toBeLessThan(b[1]);
  });
});
